steps.code:
# Let's fetch all expenses for all groups and look for ones matching Venmo descriptions.
for g in groups:
    group_id = g['group_id']
    page_index = 0
    while True:
        page = apis.splitwise.show_group_expenses(
            group_id=group_id,
            access_token=splitwise_login['access_token'],
            page_index=page_index,
            page_limit=20
        )
        for exp in page:
            desc = exp['description'].lower()
            if any(keyword in desc for keyword in ['new tv', 'office party', 'new laptop', 'donut']):
                print(f"Group {group_id} exp {exp['expense_id']}: {exp['description']} amount={exp['paid_amount']} payer={exp['payer']['email']} created={exp['created_at']}")
        if len(page) < 20:
            break
        page_index += 1

